//   2. Tasks tab: click RUN on all 11 tasks. Expected 5–60 min each; v34_ccdc_cut is the slowest.
//      Each task is independent: if one fails, tell Claude which and the error.
//   3. Download the 11 CSVs from Drive folder "cropin_v34" into  Master Data/v34_work/gee/
//
// FILES PRODUCED (folder cropin_v34)                       -> master columns
//   v34_landsat_annual.csv   yearly Landsat NDVI/NBR/SWIR1 1985–2025 -> nc_D_max_nbr_drop, nc_D_years_continuous_forest,
//                                                                     nc_D_ndvi_1985_89, rh_*
//   v34_landtrendr_cut.csv   LandTrendr on yearly NBR to as-of year   -> nc_D_lt_n_vertices
//   v34_ccdc_cut.csv         CCDC 2000 to as-of year                  -> nc_D_cc_n_breaks
//   v34_hansen.csv           Hansen loss years within 150 m           -> nc_D_h_total_loss_px
//   v34_s2_monthly_qc.csv    S2 monthly medians, 3 yrs to as-of year  -> nc_B_*, nc_wi3/su3_NDMI, nc_sg3_NDVI, mm_SAG/NDVI/B8A_win
//   v34_s1.csv               Sentinel-1 VV/VH, 3 yrs to as-of year    -> nc_F_VH_median, nc_F_VHminusVV_median
//   v34_eth.csv              ETH canopy height 2020                    -> nc_E_eth_h, nc_E_eth_sd50
//   v34_hansen_tc.csv        Hansen tree cover 2000                    -> nc_hansen_tc2000
//   v34_b6_winter_qc.csv     S2 B6 Apr–Sep, 3 yrs to as-of year        -> mm_B6_win
//   v34_mapbiomas_history.csv MapBiomas C9 classes 1985–2023           -> lh_*
//   v34_alphaearth.csv       AlphaEarth 64-d embedding, as-of year     -> master_alphaearth
// ============================================================================
var PTS = __PTS__;   // [lon, lat, label(-1), id, set, cutoff, season_start]
var allPts = ee.FeatureCollection(PTS.map(function(r) {
  return ee.Feature(ee.Geometry.Point([r[0], r[1]]), {label: r[2], id: r[3], set: r[4], cutoff: r[5], season_start: r[6]});
}));
var region = allPts.geometry().bounds();
print('points', allPts.size());
var FOLDER = 'cropin_v34';
var CUTOFFS = __CUTOFFS__;
function strip(fc) { return fc.map(function(f) { return ee.Feature(null, f.toDictionary()); }); }
function byCutoff(fn) {
  return ee.FeatureCollection(CUTOFFS.map(function(y) { return fn(allPts.filter(ee.Filter.eq('cutoff', y)), y); })).flatten();
}

// ======================= Landsat C2 L2 (w1 / w1c) =======================
function prep(img, bands) {
  var qa = img.select('QA_PIXEL');
  var clear = qa.bitwiseAnd(1 << 1).eq(0).and(qa.bitwiseAnd(1 << 3).eq(0))
    .and(qa.bitwiseAnd(1 << 4).eq(0)).and(qa.bitwiseAnd(1 << 5).eq(0));
  var sr = img.select(bands, ['blue', 'green', 'red', 'nir', 'swir1', 'swir2'])
    .multiply(0.0000275).add(-0.2);
  var ndvi = sr.normalizedDifference(['nir', 'red']).rename('NDVI');
  var nbr = sr.normalizedDifference(['nir', 'swir2']).rename('NBR');
  return sr.addBands([ndvi, nbr]).updateMask(clear)
    .copyProperties(img, ['system:time_start']);
}
var L57 = ['SR_B1', 'SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B7'];
var L89 = ['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7'];
function landsat(start, end) {
  function get(id, b) {
    return ee.ImageCollection(id).filterBounds(region).filterDate(start, end)
      .map(function(i) { return prep(i, b); });
  }
  return get('LANDSAT/LT05/C02/T1_L2', L57).merge(get('LANDSAT/LE07/C02/T1_L2', L57))
    .merge(get('LANDSAT/LC08/C02/T1_L2', L89)).merge(get('LANDSAT/LC09/C02/T1_L2', L89))
    .sort('system:time_start');
}

// ---------- 1. yearly Landsat values per point (w1 task 1) ----------
var YEARS = ee.List.sequence(1985, 2025);
function annual(y) {
  y = ee.Number(y);
  var c = landsat(ee.Date.fromYMD(y, 1, 1), ee.Date.fromYMD(y.add(1), 1, 1));
  var empty = ee.Image.constant([0, 0, 0, 0, 0]).rename(['NDVI', 'NBR', 'swir1', 'NBR_min', 'n_clear'])
    .updateMask(0).toFloat();
  var img = ee.Image(ee.Algorithms.If(c.size().gt(0),
    c.select(['NDVI', 'NBR', 'swir1']).median()
      .addBands(c.select('NBR').min().rename('NBR_min'))
      .addBands(c.select('NDVI').count().rename('n_clear')).toFloat(),
    empty));
  return img.set('year', y).set('system:time_start', ee.Date.fromYMD(y, 7, 1).millis());
}
var annualCol = ee.ImageCollection(YEARS.map(annual));
var annualTable = annualCol.map(function(img) {
  return img.reduceRegions({collection: allPts, reducer: ee.Reducer.first(), scale: 30, tileScale: 4})
    .map(function(f) { return ee.Feature(null, f.toDictionary()).set('year', img.get('year')); });
}).flatten();
Export.table.toDrive({collection: annualTable, description: 'v34_landsat_annual', folder: FOLDER, fileFormat: 'CSV'});

// ---------- 2–3. LandTrendr and CCDC ending at each point's as-of year (w1c) ----------
function annualNBR(y) {
  y = ee.Number(y);
  var c = landsat(ee.Date.fromYMD(y, 1, 1), ee.Date.fromYMD(y.add(1), 1, 1));
  var img = ee.Image(ee.Algorithms.If(c.size().gt(0), c.select('NBR').median(),
                                      ee.Image.constant(0).rename('NBR').updateMask(0).toFloat()));
  return img.multiply(-1000).toShort().rename('NBR').set('system:time_start', ee.Date.fromYMD(y, 7, 1).millis());
}
function ltFor(pts, last) {
  var col = ee.ImageCollection(ee.List.sequence(1985, last).map(annualNBR));
  var lt = ee.Algorithms.TemporalSegmentation.LandTrendr({
    timeSeries: col, maxSegments: 6, spikeThreshold: 0.9, vertexCountOvershoot: 3,
    preventOneYearRecovery: true, recoveryThreshold: 0.25, pvalThreshold: 0.05,
    bestModelProportion: 0.75, minObservationsNeeded: 6}).select('LandTrendr');
  return lt.reduceRegions({collection: pts, reducer: ee.Reducer.first(), scale: 30, tileScale: 8})
    .map(function(f) { return ee.Feature(null, f.toDictionary()); });
}
function ccdcFor(pts, last) {
  var ccdc = ee.Algorithms.TemporalSegmentation.Ccdc({
    collection: landsat('2000-01-01', (last + 1) + '-01-01').select(['green', 'red', 'nir', 'swir1', 'swir2', 'NDVI', 'NBR']),
    breakpointBands: ['green', 'red', 'nir', 'swir1', 'swir2'], tmaskBands: ['green', 'swir2'],
    minObservations: 6, chiSquareProbability: 0.99, minNumOfYearsScaler: 1.33, dateFormat: 1,
    lambda: 0.002, maxIterations: 10000});
  return ccdc.select(['tStart', 'tEnd', 'tBreak', 'numObs', 'changeProb', 'NDVI_coefs', 'NDVI_rmse',
                      'NDVI_magnitude', 'NBR_magnitude', 'swir1_magnitude'])
    .reduceRegions({collection: pts, reducer: ee.Reducer.first(), scale: 30, tileScale: 16})
    .map(function(f) { return ee.Feature(null, f.toDictionary()); });
}
var ltAll = ee.FeatureCollection(CUTOFFS.map(function(y) { return ltFor(allPts.filter(ee.Filter.eq('cutoff', y)), y); })).flatten();
var ccAll = ee.FeatureCollection(CUTOFFS.map(function(y) { return ccdcFor(allPts.filter(ee.Filter.eq('cutoff', y)), y); })).flatten();
Export.table.toDrive({collection: ltAll, description: 'v34_landtrendr_cut', folder: FOLDER, fileFormat: 'CSV'});
Export.table.toDrive({collection: ccAll, description: 'v34_ccdc_cut', folder: FOLDER, fileFormat: 'CSV'});

// ---------- 4. Hansen loss years within 150 m (w1 task 4) ----------
var hansen = ee.Image('UMD/hansen/global_forest_change_2025_v1_13');
var lossyear = hansen.select('lossyear');
var hTable = lossyear.reduceRegions({collection: allPts.map(function(f) { return f.buffer(150); }),
    reducer: ee.Reducer.frequencyHistogram(), scale: 30, tileScale: 4})
  .map(function(f) { return ee.Feature(null, f.toDictionary()); });
var tc = hansen.select('treecover2000').reduceRegions({collection: allPts, reducer: ee.Reducer.first(), scale: 30})
  .map(function(f) { return ee.Feature(null, {id: f.get('id'), set: f.get('set'), treecover2000: f.get('first')}); });
Export.table.toDrive({collection: hTable.merge(tc), description: 'v34_hansen', folder: FOLDER, fileFormat: 'CSV'});

// ======================= Sentinel-2 / Sentinel-1, 3 years to the as-of year (w2) =======================
function win(y) { return [ee.Date.fromYMD(y - 2, 1, 1), ee.Date.fromYMD(y + 1, 1, 1)]; }
var CS = ee.ImageCollection('GOOGLE/CLOUD_SCORE_PLUS/V1/S2_HARMONIZED');
var S2B = ['B2', 'B3', 'B4', 'B5', 'B8', 'B8A', 'B11'];
function s2monthly(pts, y) {
  var reg = pts.geometry().bounds();
  return ee.FeatureCollection(ee.List.sequence(0, 35).map(function(i) {
    var start = win(y)[0].advance(i, 'month');
    var c = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED').filterBounds(reg)
      .filterDate(start, start.advance(1, 'month')).linkCollection(CS, ['cs'])
      .map(function(im) { return im.updateMask(im.select('cs').gte(0.6)); }).select(S2B);
    var empty = ee.Image.constant([0, 0, 0, 0, 0, 0, 0, 0]).rename(S2B.concat(['n_clear'])).updateMask(0).toFloat();
    var img = ee.Image(ee.Algorithms.If(c.size().gt(0),
      c.median().addBands(c.select('B8').count().rename('n_clear')).toFloat(), empty));
    return strip(img.reduceRegions({collection: pts, reducer: ee.Reducer.first(), scale: 10, tileScale: 4}))
      .map(function(f) { return f.set('month', start.format('YYYY-MM')); });
  })).flatten();
}
// ---------- 5. ----------
Export.table.toDrive({collection: byCutoff(s2monthly), description: 'v34_s2_monthly_qc', folder: FOLDER, fileFormat: 'CSV'});

function s1stats(pts, y) {
  var w = win(y);
  var c = ee.ImageCollection('COPERNICUS/S1_GRD').filterBounds(pts.geometry().bounds()).filterDate(w[0], w[1])
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
    .select(['VV', 'VH', 'angle'])
    .map(function(im) { return im.addBands(im.select('VH').subtract(im.select('VV')).rename('VHminusVV')); });
  var red = ee.Reducer.median().combine(ee.Reducer.percentile([10, 90]), '', true)
    .combine(ee.Reducer.stdDev(), '', true).combine(ee.Reducer.count(), '', true);
  var img = c.select(['VV', 'VH', 'VHminusVV']).reduce(red).addBands(c.select('angle').median().rename('angle_median'));
  return strip(img.reduceRegions({collection: pts, reducer: ee.Reducer.first(), scale: 10, tileScale: 8}));
}
// ---------- 6. ----------
Export.table.toDrive({collection: byCutoff(s1stats), description: 'v34_s1', folder: FOLDER, fileFormat: 'CSV'});

// ======================= structure (w3) =======================
function sample(img, pts, scale, ts) {
  return strip(img.reduceRegions({collection: pts, reducer: ee.Reducer.first(), scale: scale, tileScale: ts || 4}));
}
// ---------- 7. ETH canopy height 2020 ----------
var eth = ee.Image('users/nlang/ETH_GlobalCanopyHeight_2020_10m_v1').select([0], ['h']);
var ethSd = ee.Image('users/nlang/ETH_GlobalCanopyHeightSD_2020_10m_v1').select([0], ['h_sd']);
var meanSd = ee.Reducer.mean().combine(ee.Reducer.stdDev(), '', true);
var ethImg = eth.rename('eth_h').addBands(ethSd.rename('eth_h_modelsd'))
  .addBands(eth.reduceNeighborhood({reducer: meanSd, kernel: ee.Kernel.circle(15, 'meters')}).rename(['eth_h_mean15', 'eth_h_sd15']))
  .addBands(eth.reduceNeighborhood({reducer: meanSd, kernel: ee.Kernel.circle(50, 'meters')}).rename(['eth_h_mean50', 'eth_h_sd50']));
Export.table.toDrive({collection: sample(ethImg, allPts, 10), description: 'v34_eth', folder: FOLDER, fileFormat: 'CSV'});
// ---------- 8. Hansen tree cover 2000 ----------
Export.table.toDrive({collection: sample(ee.Image('UMD/hansen/global_forest_change_2025_v1_13').select('treecover2000'), allPts, 30),
  description: 'v34_hansen_tc', folder: FOLDER, fileFormat: 'CSV'});

// ======================= 9. winter B6, Apr–Sep, 3 years to the as-of year (m1) =======================
function b6winter(pts, y) {
  var reg = pts.geometry().bounds();
  var months = [];
  [y - 2, y - 1, y].forEach(function(yr) { for (var m = 4; m <= 9; m++) { months.push([yr, m]); } });
  return ee.FeatureCollection(months.map(function(ym) {
    var start = ee.Date.fromYMD(ym[0], ym[1], 1);
    var c = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED').filterBounds(reg)
      .filterDate(start, start.advance(1, 'month')).linkCollection(CS, ['cs'])
      .map(function(im) { return im.updateMask(im.select('cs').gte(0.6)); }).select(['B6']);
    var empty = ee.Image.constant([0, 0]).rename(['B6', 'n_clear']).updateMask(0).toFloat();
    var img = ee.Image(ee.Algorithms.If(c.size().gt(0),
      c.median().addBands(c.count().rename('n_clear')).toFloat(), empty));
    return strip(img.reduceRegions({collection: pts, reducer: ee.Reducer.first(), scale: 10, tileScale: 4}))
      .map(function(f) { return f.set('month', start.format('YYYY-MM')); });
  })).flatten();
}
Export.table.toDrive({collection: byCutoff(b6winter), description: 'v34_b6_winter_qc', folder: FOLDER, fileFormat: 'CSV'});

// ======================= 10. MapBiomas Collection 9 history (m2) =======================
var mbc9 = ee.Image('projects/mapbiomas-public/assets/brazil/lulc/collection9/mapbiomas_collection90_integration_v1');
print('bands', mbc9.bandNames());
Export.table.toDrive({collection: strip(mbc9.reduceRegions({collection: allPts, reducer: ee.Reducer.first(), scale: 30, tileScale: 4})),
  description: 'v34_mapbiomas_history', folder: FOLDER, fileFormat: 'CSV'});

// ======================= 11. AlphaEarth embedding at the as-of year (p7) =======================
var emb = ee.ImageCollection('GOOGLE/SATELLITE_EMBEDDING/V1/ANNUAL');
var years = emb.aggregate_array('system:time_start').map(function(t) { return ee.Date(t).get('year'); }).distinct().sort();
print('AlphaEarth years available', years);
var lastYear = ee.Number(years.reduce(ee.Reducer.max()));
var aeOut = ee.FeatureCollection(CUTOFFS.map(function(y) {
  var yy = ee.Number(y).min(lastYear);
  var img = emb.filter(ee.Filter.calendarRange(yy, yy, 'year')).mosaic();
  return img.reduceRegions({collection: allPts.filter(ee.Filter.eq('cutoff', y)), reducer: ee.Reducer.first(), scale: 10, tileScale: 4})
    .map(function(f) { return ee.Feature(null, f.toDictionary()).set('emb_year', yy); });
})).flatten();
Export.table.toDrive({collection: aeOut, description: 'v34_alphaearth', folder: FOLDER, fileFormat: 'CSV'});

Map.setCenter(-51, -27, 6);
Map.addLayer(allPts, {color: '750014'}, 'QC Nov points');
